RETRY_STATUSES = {408, 429, 500, 502, 503, 504}
SAFE_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}


def call_with_retries(send, method, sleep, rng, max_attempts=4, base=0.5, cap=8.0, idempotency_key=None):
    safe = method.upper() in SAFE_METHODS or idempotency_key is not None
    attempt = 0
    while True:
        attempt += 1
        error = None
        response = None
        try:
            response = send()
        except (ConnectionError, TimeoutError) as e:
            error = e
        retryable = error is not None or response[0] in RETRY_STATUSES
        if not (retryable and safe and attempt < max_attempts):
            if error is not None:
                raise error
            return response
        delay = None
        if response is not None:
            for name, value in response[1].items():
                if name.lower() == "retry-after" and str(value).strip().isdigit():
                    delay = int(str(value).strip())
        if delay is None:
            delay = rng.uniform(0, min(cap, base * 2 ** (attempt - 1)))
        sleep(delay)

