class MaxRng:
    def uniform(self, low, high):
        return high

class Script:
    def __init__(self, *outcomes):
        self.outcomes = list(outcomes)
        self.calls = 0
    def __call__(self):
        self.calls += 1
        outcome = self.outcomes.pop(0)
        if isinstance(outcome, BaseException):
            raise outcome
        return outcome

def run(script, method="GET", **kwargs):
    slept = []
    result = call_with_retries(script, method, slept.append, MaxRng(), **kwargs)
    return result, slept

@test("success needs no retry")
def _():
    check_eq(run(Script((200, {}))), ((200, {}), []))

@test("backing off exponentially")
def _():
    s = Script((503, {}), (502, {}), (500, {}), (200, {"ok": "1"}))
    check_eq(run(s), ((200, {"ok": "1"}), [0.5, 1.0, 2.0]))

@test("the cap and the attempt limit")
def _():
    s = Script(*[(503, {})] * 6)
    result, slept = run(s, max_attempts=6, base=1, cap=5)
    check_eq(result, (503, {}))
    check_eq(slept, [1, 2, 4, 5, 5])
    check_eq(s.calls, 6)

@test("Retry-After wins")
def _():
    s = Script((429, {"retry-after": "7"}), (429, {"Retry-After": "soon"}), (200, {}))
    check_eq(run(s)[1], [7, 1.0])

@test("network errors")
def _():
    s = Script(ConnectionError("reset"), TimeoutError("slow"), (200, {}))
    check_eq(run(s), ((200, {}), [0.5, 1.0]))
    s = Script(*[ConnectionError("down")] * 4)
    check_raises(ConnectionError, run, s)
    check_eq(s.calls, 4)
    s = Script(ValueError("bug"))
    check_raises(ValueError, run, s)
    check_eq(s.calls, 1)

@test("not retried")
def _():
    for status in (400, 401, 404, 422, 501):
        s = Script((status, {}), (200, {}))
        check_eq(run(s), ((status, {}), []))

@test("POST only with an idempotency key")
def _():
    s = Script((503, {}), (200, {}))
    check_eq(run(s, method="post"), ((503, {}), []))
    s = Script((503, {}), (200, {}))
    check_eq(run(s, method="POST", idempotency_key="k1"), ((200, {}), [0.5]))
    s = Script(ConnectionError("lost"), (201, {}))
    check_raises(ConnectionError, run, s, method="PATCH")
    s = Script((500, {}), (200, {}))
    check_eq(run(s, method="delete")[0], (200, {}))

